94	  nodes?: $ReadOnlyArray<ASTNode> | ASTNode | void,
95	  source?: ?Source,
96	  positions?: ?$ReadOnlyArray<number>,
97	  path?: ?$ReadOnlyArray<string | number>,
98	  originalError?: ?Error & { +extensions: mixed },
99	  extensions?: ?{ [key: string]: mixed },
100	) {
101	  // Compute list of blame nodes.
102	  const _nodes = Array.isArray(nodes)
103	    ? nodes.length !== 0
