15	function fixIndent(str: string): string {
16	  const trimmedStr = str
17	    .replace(/^\n*/m, '') //  remove leading newline
18	    .replace(/[ \t]*$/, ''); // remove trailing spaces and tabs
19	  const indentMatch = /^[ \t]*/.exec(trimmedStr);
20	  invariant(Array.isArray(indentMatch));
21	  const indent = indentMatch[0]; // figure out indent
22	  return trimmedStr.replace(RegExp('^' + indent, 'mg'), ''); // remove indent
